select cron.schedule('learn-sync-every-20min','*/20 * * * *', $$select net.http_post(url:='https://oicqtpjjwmgsiluvkmpu.supabase.co/functions/v1/ads-manager', headers:=jsonb_build_object('Content-Type','application/json','x-cron-secret',(select value from public.app_secrets where key='ads_cron_secret')), body:='{"action":"learn_sync","max_accounts":2}'::jsonb, timeout_milliseconds:=150000)$$);
select cron.schedule('learn-pages-every-10min','*/10 * * * *', $$select net.http_post(url:='https://oicqtpjjwmgsiluvkmpu.supabase.co/functions/v1/ads-manager', headers:=jsonb_build_object('Content-Type','application/json','x-cron-secret',(select value from public.app_secrets where key='ads_cron_secret')), body:='{"action":"learn_pages","limit":8}'::jsonb, timeout_milliseconds:=150000)$$);
